using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Linq;
using System.Windows.Forms;

namespace AppShelf {
 public static class Theme {
  public static Color Bg=Color.FromArgb(245,247,250),Side=Color.FromArgb(22,38,43),Card=Color.White,Raised=Color.FromArgb(235,241,242),Line=Color.FromArgb(225,232,234),Text=Color.FromArgb(29,48,54),Muted=Color.FromArgb(113,130,136),Accent=Color.FromArgb(14,139,119),Mint=Color.FromArgb(110,219,182);
  public static Label Label(string text,float size,Color color,bool bold){return new Label{Text=text,ForeColor=color,Font=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular),AutoSize=false,AutoEllipsis=true,BackColor=Color.Transparent};}
  public static void Apply(Form f){f.BackColor=Bg;f.ForeColor=Text;f.Font=new Font("Segoe UI",10);f.AutoScaleMode=AutoScaleMode.Dpi;f.StartPosition=FormStartPosition.CenterScreen;try{f.Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);}catch{}}
  public static GraphicsPath Round(Rectangle r,int radius){radius=Math.Max(1,Math.Min(radius,Math.Min(r.Width,r.Height)/2));var p=new GraphicsPath();int d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
  public static Image Logo(){try{using(var stream=typeof(Theme).Assembly.GetManifestResourceStream("AppShelf.Logo")){return new Bitmap(Image.FromStream(stream));}}catch{return Monogram("A",64);}}
  public static Bitmap Monogram(string name,int size){var bmp=new Bitmap(size,size);using(var g=Graphics.FromImage(bmp)){g.SmoothingMode=SmoothingMode.AntiAlias;int hash=(name??"A").Aggregate(0,(a,c)=>unchecked(a*31+c))&0x7fffffff;var colors=new[]{Color.FromArgb(218,239,231),Color.FromArgb(226,232,250),Color.FromArgb(252,234,213),Color.FromArgb(237,225,248),Color.FromArgb(220,239,244)};using(var b=new SolidBrush(colors[hash%colors.Length]))using(var p=Round(new Rectangle(1,1,size-2,size-2),10))g.FillPath(b,p);using(var font=new Font("Segoe UI",size*.32f,FontStyle.Bold))TextRenderer.DrawText(g,String.IsNullOrEmpty(name)?"A":name.Substring(0,1).ToUpperInvariant(),font,new Rectangle(0,0,size,size),Color.FromArgb(65,93,96),TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}return bmp;}
  public static Bitmap AppIcon(InstalledApp app,int size){try{string raw=Environment.ExpandEnvironmentVariables(app.IconPath??"").Trim();string path;if(raw.StartsWith("\"")){int end=raw.IndexOf('"',1);path=end>0?raw.Substring(1,end-1):"";}else{int comma=raw.LastIndexOf(',');path=comma>0?raw.Substring(0,comma):raw;}if(!Path.IsPathRooted(path)||!File.Exists(path))return Monogram(app.Name,size);using(var icon=Icon.ExtractAssociatedIcon(path)){if(icon==null)return Monogram(app.Name,size);using(var original=icon.ToBitmap()){var result=new Bitmap(size,size);using(var g=Graphics.FromImage(result)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(original,new Rectangle(3,3,size-6,size-6));}return result;}}}catch{return Monogram(app.Name,size);}}
  public static void Grid(DataGridView grid){grid.Dock=DockStyle.Fill;grid.BackgroundColor=Card;grid.BorderStyle=BorderStyle.None;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.AllowUserToResizeRows=false;grid.RowHeadersVisible=false;grid.MultiSelect=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.AutoGenerateColumns=false;grid.EnableHeadersVisualStyles=false;grid.GridColor=Color.FromArgb(239,243,244);grid.CellBorderStyle=DataGridViewCellBorderStyle.SingleHorizontal;grid.ColumnHeadersBorderStyle=DataGridViewHeaderBorderStyle.None;grid.ColumnHeadersHeight=44;grid.RowTemplate.Height=62;grid.DefaultCellStyle=new DataGridViewCellStyle{BackColor=Card,ForeColor=Text,SelectionBackColor=Color.FromArgb(227,243,237),SelectionForeColor=Color.FromArgb(12,100,86),Padding=new Padding(12,0,5,0)};grid.ColumnHeadersDefaultCellStyle=new DataGridViewCellStyle{BackColor=Color.FromArgb(250,252,252),ForeColor=Muted,Font=new Font("Segoe UI",9),Padding=new Padding(12,0,0,0)};grid.DataBindingComplete+=(s,e)=>grid.ClearSelection();}
  public static void Glyph(Graphics g,string kind,Rectangle area,Color color){g.SmoothingMode=SmoothingMode.AntiAlias;var state=g.Save();g.TranslateTransform(area.X,area.Y);g.ScaleTransform(area.Width/24f,area.Height/24f);using(var pen=new Pen(color,1.7f)){pen.StartCap=pen.EndCap=LineCap.Round;pen.LineJoin=LineJoin.Round;
   if(kind=="apps"){foreach(var r in new[]{new Rectangle(3,3,7,7),new Rectangle(14,3,7,7),new Rectangle(3,14,7,7),new Rectangle(14,14,7,7)})using(var p=Round(r,2))g.DrawPath(pen,p);}
   else if(kind=="restore"){g.DrawArc(pen,4,4,16,16,205,290);g.DrawLines(pen,new[]{new Point(3,3),new Point(3,10),new Point(10,10)});g.DrawLines(pen,new[]{new Point(12,8),new Point(12,12),new Point(16,14)});}
   else if(kind=="scan"){g.DrawEllipse(pen,4,3,12,12);g.DrawLine(pen,14,14,21,21);g.DrawLine(pen,8,9,12,9);g.DrawLine(pen,10,7,10,11);}
   else if(kind=="folder"){g.DrawLines(pen,new[]{new Point(3,7),new Point(3,19),new Point(21,19),new Point(21,7),new Point(11,7),new Point(9,4),new Point(3,4),new Point(3,7)});}
   else if(kind=="refresh"){g.DrawArc(pen,4,4,16,16,40,290);g.DrawLines(pen,new[]{new Point(21,3),new Point(21,10),new Point(14,10)});}
   else if(kind=="log"){g.DrawRectangle(pen,5,3,14,18);g.DrawLine(pen,9,8,15,8);g.DrawLine(pen,9,12,15,12);g.DrawLine(pen,9,16,13,16);}
   else if(kind=="trash"){g.DrawLine(pen,5,6,19,6);g.DrawLine(pen,9,3,15,3);g.DrawLines(pen,new[]{new Point(7,9),new Point(8,21),new Point(16,21),new Point(17,9)});g.DrawLine(pen,10,10,10,17);g.DrawLine(pen,14,10,14,17);}
   else if(kind=="shield"){g.DrawLines(pen,new[]{new Point(12,2),new Point(21,6),new Point(19,16),new Point(12,22),new Point(5,16),new Point(3,6),new Point(12,2)});g.DrawLines(pen,new[]{new Point(8,12),new Point(11,15),new Point(16,9)});}
  }g.Restore(state);}
 }
 public class SoftButton:Button {
  public bool Primary,Navigation,Active;public string GlyphName;bool hover,down;
  public SoftButton(string text,bool primary){Text=text;Primary=primary;Height=44;Width=154;FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;Cursor=Cursors.Hand;Font=new Font("Segoe UI",10,FontStyle.Bold);Margin=new Padding(0,0,10,8);SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.AllPaintingInWmPaint|ControlStyles.ResizeRedraw,true);}
  protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hover=false;down=false;Invalidate();base.OnMouseLeave(e);}protected override void OnMouseDown(MouseEventArgs e){down=true;Invalidate();base.OnMouseDown(e);}protected override void OnMouseUp(MouseEventArgs e){down=false;Invalidate();base.OnMouseUp(e);}
  protected override void OnPaintBackground(PaintEventArgs e){e.Graphics.Clear(Parent==null?Theme.Bg:Parent.BackColor);}
  protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Parent==null?Theme.Bg:Parent.BackColor);g.SmoothingMode=SmoothingMode.AntiAlias;Color fill=Navigation?(Active?Color.FromArgb(39,73,72):(hover?Color.FromArgb(32,54,59):Theme.Side)):(Primary?(down?Color.FromArgb(9,108,93):(hover?Color.FromArgb(11,123,105):Theme.Accent)):(hover?Theme.Raised:Theme.Card));Color ink=Navigation?(Active?Theme.Mint:Color.FromArgb(191,209,209)):(Primary?Color.White:Theme.Text);if(!Enabled){fill=Theme.Line;ink=Theme.Muted;}int inset=1;using(var path=Theme.Round(new Rectangle(inset,inset,Width-3,Height-3),11)){using(var brush=new SolidBrush(fill))g.FillPath(brush,path);if(!Navigation&&!Primary)using(var pen=new Pen(Theme.Line))g.DrawPath(pen,path);if(Focused&&ShowFocusCues)using(var pen=new Pen(Navigation?Theme.Mint:Theme.Accent,2)){pen.DashStyle=DashStyle.Dot;g.DrawPath(pen,path);}}
   var rect=new Rectangle(12,0,Width-24,Height);if(!String.IsNullOrEmpty(GlyphName)){int left=Navigation?16:18;Theme.Glyph(g,GlyphName,new Rectangle(left,(Height-20)/2,20,20),ink);rect=new Rectangle(left+31,0,Width-left-40,Height);}
   TextRenderer.DrawText(g,Text,Font,rect,ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|(Navigation||!String.IsNullOrEmpty(GlyphName)?TextFormatFlags.Left:TextFormatFlags.HorizontalCenter));}
 }
 public class Card:Panel {public Card(){BackColor=Theme.Card;Padding=new Padding(16);DoubleBuffered=true;}protected override void OnPaintBackground(PaintEventArgs e){e.Graphics.Clear(Parent==null?Theme.Bg:Parent.BackColor);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Theme.Round(new Rectangle(1,1,Width-3,Height-3),15)){using(var brush=new SolidBrush(Theme.Card))e.Graphics.FillPath(brush,path);using(var pen=new Pen(Theme.Line))e.Graphics.DrawPath(pen,path);}}}
}

